return [{ json: {
  "sheetId": "PASTE_SHEET_ID",
  "business": "Your Business",
  "twilioNumber": "+15550000000",
  "text": "Hi, this is {business}. Sorry we missed your call! How can we help? Reply here and we'll get right back to you."
} }];

const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

const b = $('Twilio call status').first().json.body || {};
const st = String(b.CallStatus || b.DialCallStatus || '').toLowerCase();
if (!['no-answer','busy','failed','canceled'].includes(st) || !b.From) return [];
return [{ json: { caller: b.From, status: st, text: fill(C.text, { business: C.business }) } }];
